import { Component, inject, OnInit, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router';
import { MatCardModule } from '@angular/material/card';
import { MatIconModule } from '@angular/material/icon';
import { MatButtonModule } from '@angular/material/button';
import { MatProgressBarModule } from '@angular/material/progress-bar';
import { MatChipsModule } from '@angular/material/chips';
import { AuthService } from '../../core/auth/auth.service';
import { UserService } from '../../core/services/user.service';
import { ROLE_LABELS, UtilisateurDto } from '../../core/models/user.model';

interface StatCard {
  label: string;
  value: string | number;
  icon: string;
  color: string;
  trend?: string;
  trendUp?: boolean;
}

@Component({
  selector: 'app-dashboard',
  standalone: true,
  imports: [
    CommonModule, RouterLink,
    MatCardModule, MatIconModule, MatButtonModule,
    MatProgressBarModule, MatChipsModule,
  ],
  template: `
    <div class="dashboard">

      <!-- ── Welcome Header ─────────────────────────────────── -->
      <div class="welcome-section">
        <div class="welcome-text">
          <h1>Bonjour, {{ firstName() }} 👋</h1>
          <p>Bienvenue sur le Système de Gestion des Affaires BTP — Demathieu &amp; Bard</p>
        </div>
        <div class="welcome-badge">
          <span class="role-badge {{ auth.userRole() }}">{{ roleLabel() }}</span>
        </div>
      </div>

      <!-- ── Stats Cards ────────────────────────────────────── -->
      <div class="stats-grid">
        @for (stat of stats; track stat.label) {
          <div class="stat-card" [style.--accent]="stat.color">
            <div class="stat-icon" [style.background]="stat.color + '18'">
              <mat-icon [style.color]="stat.color">{{ stat.icon }}</mat-icon>
            </div>
            <div class="stat-body">
              <span class="stat-value">{{ stat.value }}</span>
              <span class="stat-label">{{ stat.label }}</span>
            </div>
            @if (stat.trend) {
              <div class="stat-trend" [class.up]="stat.trendUp" [class.down]="!stat.trendUp">
                <mat-icon>{{ stat.trendUp ? 'trending_up' : 'trending_down' }}</mat-icon>
                {{ stat.trend }}
              </div>
            }
          </div>
        }
      </div>

      <!-- ── Main Grid ──────────────────────────────────────── -->
      <div class="main-grid">

        <!-- Activité récente -->
        <div class="db-card activity-card">
          <div class="card-header">
            <h3>Activité récente</h3>
            <span class="card-subtitle">Dernières actions dans le système</span>
          </div>
          <div class="activity-list">
            @for (item of activities; track item.id) {
              <div class="activity-item">
                <div class="act-icon" [style.background]="item.color + '18'">
                  <mat-icon [style.color]="item.color">{{ item.icon }}</mat-icon>
                </div>
                <div class="act-body">
                  <span class="act-title">{{ item.title }}</span>
                  <span class="act-sub">{{ item.subtitle }}</span>
                </div>
                <span class="act-time">{{ item.time }}</span>
              </div>
            }
          </div>
        </div>

        <!-- Panel droit -->
        <div class="right-panels">

          <!-- Accès rapides -->
          <div class="db-card quick-card">
            <div class="card-header">
              <h3>Accès rapides</h3>
            </div>
            <div class="quick-grid">
              @for (action of quickActions; track action.label) {
                <button class="quick-btn"
                        [routerLink]="action.disabled ? null : action.route"
                        [class.disabled-btn]="action.disabled"
                        [title]="action.disabled ? 'Bientôt disponible' : ''">
                  <div class="qbtn-icon" [style.background]="action.color + '15'">
                    <mat-icon [style.color]="action.color">{{ action.icon }}</mat-icon>
                  </div>
                  <span class="qbtn-label">{{ action.label }}</span>
                  @if (action.disabled) {
                    <span class="qbtn-soon">soon</span>
                  }
                </button>
              }
            </div>
          </div>

          <!-- Utilisateurs récents (ADMIN) -->
          @if (auth.hasRole('ADMIN')) {
            <div class="db-card users-mini-card">
              <div class="card-header">
                <h3>Utilisateurs</h3>
                <a routerLink="/users" class="card-link">Voir tout →</a>
              </div>
              @if (recentUsers().length > 0) {
                <div class="users-mini-list">
                  @for (user of recentUsers(); track user.id) {
                    <div class="user-mini-item">
                      <div class="user-mini-avatar">
                        {{ (user.prenom[0] + user.nom[0]).toUpperCase() }}
                      </div>
                      <div class="user-mini-info">
                        <span class="user-mini-name">{{ user.prenom }} {{ user.nom }}</span>
                        <span class="role-badge {{ user.role }} small">{{ ROLE_LABELS[user.role] }}</span>
                      </div>
                      <div class="status-badge" [class]="user.actif ? 'actif' : 'inactif'">
                        {{ user.actif ? 'Actif' : 'Inactif' }}
                      </div>
                    </div>
                  }
                </div>
              } @else {
                <div class="empty-state">
                  <mat-icon>group</mat-icon>
                  <span>Chargement...</span>
                </div>
              }
            </div>
          }

        </div>
      </div>

      <!-- ── Phases Banner ──────────────────────────────────── -->
      <div class="phases-banner">
        <div class="phase-item done">
          <mat-icon>check_circle</mat-icon>
          <span>Infrastructure</span>
        </div>
        <div class="phase-separator"></div>
        <div class="phase-item done">
          <mat-icon>check_circle</mat-icon>
          <span>User Service</span>
        </div>
        <div class="phase-separator"></div>
        <div class="phase-item current">
          <mat-icon>radio_button_checked</mat-icon>
          <span>Frontend Auth</span>
        </div>
        <div class="phase-separator"></div>
        <div class="phase-item pending">
          <mat-icon>radio_button_unchecked</mat-icon>
          <span>Affaires & Plans</span>
        </div>
        <div class="phase-separator"></div>
        <div class="phase-item pending">
          <mat-icon>radio_button_unchecked</mat-icon>
          <span>Contrôles & Visas</span>
        </div>
        <div class="phase-separator"></div>
        <div class="phase-item pending">
          <mat-icon>radio_button_unchecked</mat-icon>
          <span>Notifications</span>
        </div>
      </div>

    </div>
  `,
  styles: [`
    .dashboard { display: flex; flex-direction: column; gap: 24px; }

    /* Welcome */
    .welcome-section {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;

      h1 {
        font-size: 1.6rem;
        font-weight: 700;
        color: var(--db-navy);
        margin: 0 0 4px;
        letter-spacing: -.02em;
      }

      p {
        margin: 0;
        color: var(--db-text-secondary);
        font-size: .9rem;
      }
    }

    /* Stat Cards */
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
      gap: 16px;
    }

    .stat-card {
      background: #fff;
      border-radius: 10px;
      padding: 20px;
      display: flex;
      align-items: center;
      gap: 16px;
      box-shadow: 0 1px 3px rgba(0,0,0,.06);
      border: 1px solid #E8EDF3;
      border-left: 3px solid var(--accent);
      transition: box-shadow .2s;
      &:hover { box-shadow: 0 4px 12px rgba(0,0,0,.08); }
    }

    .stat-icon {
      width: 48px;
      height: 48px;
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;

      mat-icon { font-size: 1.4rem; width: 1.4rem; height: 1.4rem; }
    }

    .stat-body { flex: 1; }

    .stat-value {
      display: block;
      font-size: 1.75rem;
      font-weight: 800;
      color: var(--db-text);
      letter-spacing: -.03em;
      line-height: 1;
    }

    .stat-label {
      font-size: .8rem;
      color: var(--db-text-secondary);
      font-weight: 500;
      margin-top: 3px;
      display: block;
    }

    .stat-trend {
      display: flex;
      align-items: center;
      gap: 2px;
      font-size: .75rem;
      font-weight: 600;
      padding: 2px 8px;
      border-radius: 20px;

      mat-icon { font-size: .9rem; width: .9rem; height: .9rem; }
      &.up   { color: #065F46; background: #D1FAE5; }
      &.down { color: #991B1B; background: #FEE2E2; }
    }

    /* Main grid */
    .main-grid {
      display: grid;
      grid-template-columns: 1fr 360px;
      gap: 20px;
      align-items: start;
    }

    .db-card {
      background: #fff;
      border-radius: 10px;
      box-shadow: 0 1px 3px rgba(0,0,0,.06);
      border: 1px solid #E8EDF3;
      overflow: hidden;
    }

    .card-header {
      padding: 18px 20px 14px;
      border-bottom: 1px solid #F0F4F8;
      display: flex;
      justify-content: space-between;
      align-items: baseline;

      h3 {
        font-size: .95rem;
        font-weight: 700;
        color: var(--db-text);
        margin: 0;
      }
    }

    .card-subtitle { font-size: .8rem; color: var(--db-text-secondary); }
    .card-link { font-size: .8rem; color: var(--db-orange); font-weight: 600; text-decoration: none; }

    /* Activity */
    .activity-list { padding: 8px 0; }

    .activity-item {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 12px 20px;
      transition: background .15s;
      &:hover { background: #F8FAFC; }
    }

    .act-icon {
      width: 36px;
      height: 36px;
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      mat-icon { font-size: 1.1rem; width: 1.1rem; height: 1.1rem; }
    }

    .act-body { flex: 1; display: flex; flex-direction: column; }
    .act-title { font-size: .875rem; font-weight: 500; color: var(--db-text); }
    .act-sub   { font-size: .78rem; color: var(--db-text-secondary); margin-top: 1px; }
    .act-time  { font-size: .75rem; color: var(--db-text-light); white-space: nowrap; }

    /* Right panels */
    .right-panels { display: flex; flex-direction: column; gap: 16px; }

    /* Quick actions */
    .quick-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 10px;
      padding: 16px;
    }

    .quick-btn {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 8px;
      padding: 16px 12px;
      border: 1px solid #E8EDF3;
      border-radius: 8px;
      background: #FAFBFC;
      cursor: pointer;
      transition: all .15s;
      position: relative;

      &:hover:not(.disabled-btn) {
        border-color: var(--db-orange);
        background: var(--db-orange-light, #FDE9E3);
      }
      &.disabled-btn { opacity: .5; cursor: not-allowed; }
    }

    .qbtn-icon {
      width: 40px;
      height: 40px;
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
      mat-icon { font-size: 1.2rem; width: 1.2rem; height: 1.2rem; }
    }

    .qbtn-label { font-size: .78rem; font-weight: 600; color: var(--db-text); text-align: center; }
    .qbtn-soon {
      position: absolute;
      top: 4px; right: 4px;
      font-size: .58rem;
      background: #E2E8F0;
      color: #64748B;
      padding: 1px 5px;
      border-radius: 10px;
      font-weight: 700;
      text-transform: uppercase;
    }

    /* Users mini */
    .users-mini-list { padding: 8px 0; }

    .user-mini-item {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 10px 16px;
      transition: background .15s;
      &:hover { background: #F8FAFC; }
    }

    .user-mini-avatar {
      width: 32px;
      height: 32px;
      border-radius: 50%;
      background: var(--db-navy);
      color: #fff;
      font-size: .75rem;
      font-weight: 700;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }

    .user-mini-info {
      flex: 1;
      display: flex;
      flex-direction: column;
      gap: 2px;
    }

    .user-mini-name { font-size: .85rem; font-weight: 500; color: var(--db-text); }

    .role-badge.small { font-size: .65rem; padding: 1px 6px; }

    .empty-state {
      padding: 24px;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 8px;
      color: var(--db-text-light);
      font-size: .85rem;

      mat-icon { font-size: 2rem; width: 2rem; height: 2rem; opacity: .4; }
    }

    /* Phases banner */
    .phases-banner {
      display: flex;
      align-items: center;
      gap: 0;
      background: var(--db-navy);
      border-radius: 10px;
      padding: 16px 24px;
      overflow-x: auto;
    }

    .phase-item {
      display: flex;
      align-items: center;
      gap: 6px;
      white-space: nowrap;
      font-size: .8rem;
      font-weight: 600;
      padding: 0 16px;

      mat-icon { font-size: 1rem; width: 1rem; height: 1rem; }

      &.done    { color: #4ADE80; }
      &.current { color: var(--db-orange); }
      &.pending { color: rgba(255,255,255,.35); }
    }

    .phase-separator {
      width: 32px;
      height: 1px;
      background: rgba(255,255,255,.2);
      flex-shrink: 0;
    }

    @media (max-width: 1100px) {
      .main-grid { grid-template-columns: 1fr; }
    }
    @media (max-width: 600px) {
      .stats-grid { grid-template-columns: 1fr 1fr; }
      .welcome-section { flex-direction: column; align-items: flex-start; }
    }
  `]
})
export class DashboardComponent implements OnInit {
  auth         = inject(AuthService);
  private userSvc = inject(UserService);

  ROLE_LABELS = ROLE_LABELS;
  recentUsers = signal<UtilisateurDto[]>([]);

  stats: StatCard[] = [
    { label: 'Affaires actives',      value: '—', icon: 'business',     color: '#1B3A5C', trend: '+2 ce mois', trendUp: true  },
    { label: 'Plans en contrôle',     value: '—', icon: 'description',  color: '#E8440E', trend: '3 en attente', trendUp: false },
    { label: 'Contrôles validés',     value: '—', icon: 'fact_check',   color: '#22C55E', trend: '+5 cette semaine', trendUp: true  },
    { label: 'Utilisateurs actifs',   value: '—', icon: 'group',        color: '#3B82F6'  },
  ];

  activities = [
    { id: 1, icon: 'person_add',   color: '#22C55E', title: 'Compte admin créé',            subtitle: 'admin@btp.fr — ADMIN',              time: "À l'instant" },
    { id: 2, icon: 'group',        color: '#3B82F6', title: 'Utilisateurs démo initialisés', subtitle: '6 comptes créés automatiquement',   time: 'Démarrage'   },
    { id: 3, icon: 'check_circle', color: '#E8440E', title: 'User Service opérationnel',     subtitle: 'Port 8084 — JWT + MongoDB',          time: 'Phase 2'     },
    { id: 4, icon: 'cloud_done',   color: '#1B3A5C', title: 'Eureka Server en ligne',        subtitle: 'Service Discovery actif',           time: 'Phase 1'     },
    { id: 5, icon: 'settings',     color: '#6B7280', title: 'API Gateway configuré',         subtitle: 'Port 8080 — JWT filter actif',       time: 'Phase 1'     },
  ];

  quickActions = [
    { label: 'Affaires',     icon: 'business',     color: '#1B3A5C', route: '/affaires',       disabled: true  },
    { label: 'Plans',        icon: 'description',  color: '#E8440E', route: '/plans',           disabled: true  },
    { label: 'Contrôles',    icon: 'fact_check',   color: '#22C55E', route: '/controles',       disabled: true  },
    { label: 'Utilisateurs', icon: 'group',        color: '#3B82F6', route: '/users',           disabled: false },
    { label: 'Mon profil',   icon: 'person',       color: '#8B5CF6', route: '/profile',         disabled: false },
    { label: 'Notifications',icon: 'notifications',color: '#F59E0B', route: '/notifications',   disabled: true  },
  ];

  firstName() { return this.auth.currentUser()?.prenom ?? 'Utilisateur'; }
  roleLabel()  { const r = this.auth.userRole(); return r ? ROLE_LABELS[r] : ''; }

  ngOnInit(): void {
    if (this.auth.hasRole('ADMIN')) {
      this.userSvc.getAll(0, 5).subscribe({
        next: page => {
          this.recentUsers.set(page.content);
          this.stats[3].value = page.totalElements;
        }
      });
    }
  }
}
